import {ORDER,CELL_ARCMIN,CELL_COUNT,cellAt,center,boundary,nearby,visibleCells,gridOrder,MIRA_CELL,parseSky,channelTransportHz} from './sky-model.js';
export function skyMarkup(){return `<main id="main" class="explorer" data-sky><section class="map-area sky-area" aria-label="SPHEREx sky map"><div class="sky-toolbar"><button data-sky-action="whole">Whole sky</button><span class="survey-name">SPHEREx DR1</span></div><div class="sky-wavelength"><label for="sky-wave">Wavelength</label><output id="sky-wave-value" for="sky-wave">Loading…</output><span data-wave-max></span><input id="sky-wave" type="range" aria-label="Wavelength" aria-orientation="vertical" min="0" max="99" value="60" step="1" disabled><span data-wave-min></span></div><div class="sky-timeline"><img id="sky-time-image" src="/assets/mira-1.png" alt="Example observation, November 2025"><div><div class="sky-time-label"><label for="sky-time">Example dates</label><output id="sky-time-value" for="sky-time">Nov 2025</output></div><input id="sky-time" type="range" min="0" max="1" step="1" value="0" aria-label="Example observation date" aria-valuetext="November 2025"><span class="sky-time-note">Two observations · same region</span></div></div><div id="aladin-sky" aria-label="Interactive SPHEREx sky image"></div><div class="sky-loading" id="sky-loading" role="status">Loading SPHEREx…</div><div class="sky-bottom"><output id="sky-coordinates">RA 266.4000° · Dec −29.0000°</output><div class="sky-zoom"><button data-sky-action="out" aria-label="Zoom out">−</button><button data-sky-action="in" aria-label="Zoom in">+</button></div></div></section><aside class="rail sky-rail"><div id="sky-selection"></div><details class="sky-coordinate-search"><summary>Go to coordinates</summary><form id="sky-coordinate-form"><div class="coord-inputs"><label>RA °<input name="ra" aria-label="Right ascension" type="number" step="any" min="0" max="359.999999" required placeholder="225.5413"></label><label>Dec °<input name="dec" aria-label="Declination" type="number" step="any" min="-90" max="90" required placeholder="59.5225"></label><button aria-label="Go to coordinates">→</button></div></form></details><button class="sky-example" data-sky-action="example">Locate real example ↗</button><details class="sky-details"><summary>Map details</summary><p>Real SPHEREx DR1 imagery, combined across observing dates. The map is spatial and spectral context; it is not a time sequence.</p><p>${CELL_COUNT.toLocaleString()} equal-area search cells. Each is ${CELL_ARCMIN.toFixed(2)}′ in equivalent-square width (about 67 native SPHEREx pixels). Cell shapes vary. This is our task grid, not detector footprints.</p><p>The displayed HiPS mosaic uses approximately 12.9″ pixels. Detailed investigations should use native Level 2 images and a boundary margin.</p><a href="https://irsa.ipac.caltech.edu/data/hips/SPHEREx/spherex_allsky_cube/properties" target="_blank" rel="noreferrer">NASA/IPAC image metadata ↗</a><p>Viewer: <a href="https://aladin.cds.unistra.fr/AladinLite/" target="_blank" rel="noreferrer">Aladin Lite</a>. <a href="/vendor/NOTICE.txt" target="_blank">Software credits</a>.</p></details></aside></main>`;}
export async function mountSky(){
 const root=document.querySelector('[data-sky]');if(!root)return()=>{};
 let dead=false,viewer,survey,overlay,selected=parseSky(location.search),timer,gridTimer,channel=62,metadata,channels=[],drawOrder=2,reviewTimer;
 const q=s=>root.querySelector(s),loading=q('#sky-loading'),panel=q('#sky-selection');
 const clean=()=>{dead=true;clearTimeout(timer);clearTimeout(gridTimer);clearTimeout(reviewTimer);};
 const coordText=p=>`RA ${p.ra.toFixed(4)}° · Dec ${p.dec<0?'−':'+'}${Math.abs(p.dec).toFixed(4)}°`;
 let reviews={};try{const saved=JSON.parse(localStorage.getItem('sate-healpix-reviews-v1')||'{}');reviews=saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{};}catch{}
 function url(){const u=new URL(location.href);u.search='';if(selected){u.searchParams.set('hpx',selected.id);u.searchParams.set('order',selected.order);}u.searchParams.set('channel',channel);history.replaceState({},'',u.pathname+u.search);}
 function coordinates(){if(dead||!viewer)return;const p=selected?center(selected.id,selected.order):(()=>{const [ra,dec]=viewer.getRaDec();return {ra,dec};})();q('#sky-coordinates').textContent=coordText(p);for(const [name,value] of [['ra',p.ra],['dec',p.dec]]){const input=q(`[name="${name}"]`);if(document.activeElement!==input)input.value=value.toFixed(4);}}
 function updatePanel(){if(dead)return;if(!selected){panel.innerHTML=`<div class="eyebrow">The sky atlas</div><h1>Choose a patch.</h1><p class="rail-intro">Click the map, then zoom in to a search cell.</p><button class="button full-width" data-sky-action="find">Find a cell for me ↗</button><div class="sky-cell-scale"><strong>6.87′</strong><span>per search cell<br>3.1 million across the sky</span></div>`;return;}
 const p=center(selected.id,selected.order),isCell=selected.order===ORDER,isMira=isCell&&selected.id===MIRA_CELL,size=(CELL_ARCMIN*2**(ORDER-selected.order)),reviewed=reviews[selected.id];
 panel.innerHTML=`<button class="back-button" data-sky-action="whole">← Whole sky</button><div class="eyebrow">${isCell?'Search cell':'Selected region'}</div><h1>${isCell?'Cell '+selected.id:'Region '+selected.id}</h1><p class="sky-size">${size<60?size.toFixed(2)+'′':(size/60).toFixed(2)+'°'} · equal-area ${isCell?'cell':'region'}</p>${isCell?`<div class="status-line"><i class="dot"></i>${reviewed?'Sample review saved':'Not reviewed'}</div>${isMira?`<div class="cell-preview"><img src="/assets/mira-1.png" alt="November observation"><img src="/assets/mira-2.png" alt="June observation"></div><a href="/observations/mira/" class="button full-width">Compare observations ↗</a>`:`<button class="button full-width" data-sky-action="review">Try a sample review ↗</button><p class="tiny">Demo only · no AI connected.</p>`}<div class="rail-actions"><button class="button outline" data-sky-action="focus">Centre this cell</button><button class="button outline" data-sky-action="find">Find another cell →</button></div><div class="sky-neighbours"><span>Neighbouring cells</span><div>${nearby(selected.id).filter(id=>id!==selected.id).map(id=>`<button data-neighbour="${id}" aria-label="Select neighbouring cell ${id}">${id}</button>`).join('')}</div></div><button class="share-button" data-sky-action="copy">Copy cell link</button>`:`<p class="rail-intro">${(4**(ORDER-selected.order)).toLocaleString()} search cells in this region.</p><button class="button full-width" data-sky-action="open">Open region ↗</button>`}`;
 }
 function pick(id,order,{focus=false}={}){selected={id,order};if(viewer&&focus){const p=center(id,order);viewer.gotoRaDec(p.ra,p.dec);viewer.setFoV(order===ORDER?.48:Math.min(150,Math.max(.48,CELL_ARCMIN/60*2**(ORDER-order)*1.4)));}updatePanel();coordinates();draw();url();}
 function draw(){if(dead||!viewer||!overlay)return;clearTimeout(gridTimer);gridTimer=setTimeout(()=>{if(dead)return;const [ra,dec]=viewer.getRaDec(),fov=viewer.getFov()[0];drawOrder=gridOrder(fov);let ids=visibleCells(ra,dec,fov,drawOrder);if(ids.length>350)ids=ids.slice(0,350);const shapes=ids.map(id=>A.polygon(boundary(id,drawOrder,drawOrder<3?8:2),{color:drawOrder===ORDER&&reviews[id]?'#80bda4':'#aac1b566',lineWidth:drawOrder===ORDER&&reviews[id]?1.8:.6}));if(selected){if(selected.order===ORDER&&fov<4)for(const id of nearby(selected.id))if(id!==selected.id)shapes.push(A.polygon(boundary(id),{color:'#b9cbb4',lineWidth:1}));shapes.push(A.polygon(boundary(selected.id,selected.order),{color:'#b8dfff',lineWidth:2.5}));}overlay.removeAll();overlay.addFootprints(shapes);},80);}
 let A;
 q('#sky-time').addEventListener('input',e=>{const i=Number(e.target.value),date=['Nov 2025','Jun 2026'][i];q('#sky-time-image').src='/assets/mira-'+(i+1)+'.png';q('#sky-time-image').alt='Example observation, '+date;q('#sky-time-value').textContent=date;e.target.setAttribute('aria-valuetext',date);});
 updatePanel();
 try{
  const result=await Promise.all([import('./vendor/aladin-3.8.1.js'),fetch('/assets/spherex-survey.json').then(r=>{if(!r.ok)throw Error('Metadata unavailable');return r.json();})]);if(dead)return clean;A=result[0].default;metadata=result[1];await A.init;if(dead)return clean;
  const requested=Number(new URLSearchParams(location.search).get('channel'));if(new URLSearchParams(location.search).has('channel')&&Number.isInteger(requested)&&requested>=0&&requested<102&&!metadata.blankFrames.includes(requested))channel=requested;
  channels=metadata.wavelengths.map((wave,id)=>({wave,id})).filter(c=>!metadata.blankFrames.includes(c.id)).sort((a,b)=>a.wave-b.wave);
  const wave=q('#sky-wave');wave.max=channels.length-1;wave.value=channels.findIndex(c=>c.id===channel);wave.disabled=false;
  q('[data-wave-max]').textContent=channels.at(-1).wave.toFixed(2)+' µm';q('[data-wave-min]').textContent=channels[0].wave.toFixed(2)+' µm';
  function waveLabel(){const label=metadata.wavelengths[channel].toFixed(3)+' µm';q('#sky-wave-value').textContent=label;wave.setAttribute('aria-valuetext',label);}waveLabel();
  wave.addEventListener('input',()=>{channel=channels[Number(wave.value)].id;waveLabel();survey?.setFrequency({unit:'Hz',value:channelTransportHz(channel)});url();});
  survey=A.imageHiPS(metadata.url,{imgFormat:'png',successCallback:h=>{if(dead)return;survey=h;h.setFrequency({unit:'Hz',value:channelTransportHz(channel)});loading.hidden=true;},errorCallback:()=>{loading.hidden=false;loading.textContent='SPHEREx imagery unavailable. Reload to retry.';}});
  const initial=selected?center(selected.id,selected.order):{ra:266.4,dec:-29};
  viewer=A.aladin('#aladin-sky',{survey,target:`${initial.ra} ${initial.dec}`,fov:selected?Math.min(360,Math.max(.48,CELL_ARCMIN/60*2**(ORDER-selected.order)*1.4)):360,projection:'AIT',cooFrame:'ICRSd',showZoomControl:false,showLayersControl:false,showFullscreenControl:false,showFrame:false,showProjectionControl:false,showStatusBar:false,showGotoControl:false,showReticle:false,showCooGrid:false,showFov:false,showCooLocation:false,log:false,inertia:false,backgroundColor:'#0c1a20'});
  overlay=A.graphicOverlay({color:'#9bb3a0',lineWidth:1});viewer.addOverlay(overlay);
  viewer.on('click',p=>{if(Number.isFinite(p.ra)&&Number.isFinite(p.dec))pick(cellAt(p.ra,p.dec,drawOrder),drawOrder);});
  viewer.on('positionChanged',()=>{coordinates();draw();});viewer.on('zoomChanged',()=>{coordinates();draw();});
  viewer.on('resizeChanged',draw);draw();coordinates();
  timer=setTimeout(()=>{if(!dead&&!loading.hidden)loading.textContent='SPHEREx is taking longer to load. You can still select a region.';},20000);
 }catch(e){if(!dead){loading.hidden=false;loading.textContent='The sky viewer could not load. Please reload in a WebGL2 browser.';}return clean;}
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!viewer)return;if(b.dataset.neighbour){pick(Number(b.dataset.neighbour),ORDER,{focus:true});return;}switch(b.dataset.skyAction){
 case'whole':selected=null;viewer.gotoRaDec(266.4,-29);viewer.setFoV(360);updatePanel();coordinates();draw();url();break;
 case'in':viewer.setFoV(Math.max(.08,viewer.getFov()[0]/2));break;
 case'out':viewer.setFoV(Math.min(360,viewer.getFov()[0]*2));break;
 case'open':case'focus':if(selected)pick(selected.id,selected.order,{focus:true});break;
 case'example':pick(MIRA_CELL,ORDER,{focus:true});break;
 case'find':{const id=selected?.order===ORDER?(selected.id+1)%CELL_COUNT:MIRA_CELL+1;pick(id,ORDER,{focus:true});break;}
 case'copy':try{await navigator.clipboard.writeText(location.href);b.textContent='Link copied';}catch{b.textContent='Copy this page’s URL';}break;
 case'review':{const id=selected.id;b.disabled=true;b.textContent='Running sample…';reviewTimer=setTimeout(()=>{reviews[id]={demo:true,date:new Date().toISOString()};try{localStorage.setItem('sate-healpix-reviews-v1',JSON.stringify(reviews));}catch{}if(selected?.id===id){updatePanel();draw();const line=q('.status-line');if(line)line.textContent='Sample complete · no analysis performed';}},1200);break;}
 }});
 q('#sky-coordinate-form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const f=new FormData(e.target),ra=Number(f.get('ra')),dec=Number(f.get('dec'));if(Number.isFinite(ra)&&Number.isFinite(dec)&&ra>=0&&ra<360&&dec>=-90&&dec<=90)pick(cellAt(ra,dec),ORDER,{focus:true});});

 return clean;
}
